   struct ContentView: View {
       var body: some View {
           VStack {
               Text("Hello, World!")
                   .font(.largeTitle)
                   .padding()
               Button(action: {
                   print("Button tapped")
               }) {
                   Text("Tap Me!")
                       .padding()
                       .background(Color.blue)
                       .foregroundColor(.white)
                       .cornerRadius(8)
               }
           }
           .padding()
       }
