     let password = "";
     for (let i = 0; i < length; i++) {
       password += charset.charAt(Math.floor(Math.random() * charset.length));
     }
     return password;
   }

   function checkPassword(password) {
     // Simulate a check against a target
     return password === "targetPassword";
   }

   bruteForcePassword(8);
